<?php $this->layout('default'); use Moves\Services\CmsShowcase as S; use Moves\Support\CmsView as V; $rows = S::slides();
$this->start('actions'); ?><a class="cms-btn-primary" href="/destaques/novo"><?= V::icon('plus') ?>Novo destaque</a><?php $this->stop(); ?>
<section class="cms-list"><?= V::listHead('Lista de destaques', count($rows) . ' registro(s)') ?><?php if ($rows === []): ?><?= V::empty('Nenhum destaque cadastrado.', 'Destaques publicados aparecem no topo da página inicial.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Destaque</th><th>Alinhamento</th><th>Ordem</th><th>Status</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($rows as $s): ?><tr><td><div class="cms-cell"><?= $s['image_path'] ? '<img class="cms-thumb" src="' . V::e($s['image_path']) . '" alt="">' : '<i class="cms-thumb">' . V::icon('layers') . '</i>' ?><div><a href="/destaques/<?= (int) $s['id'] ?>"><?= V::e($s['title']) ?></a><?= $s['link_url'] !== '' ? '<br><small>' . V::e($s['link_url']) . '</small>' : '' ?></div></div></td><td><?= V::e(S::ALIGN[$s['alignment']] ?? '') ?></td><td><?= (int) $s['sort_order'] ?></td><td><?= V::badge($s['status'], $s['status'] === 'published' ? 'Publicado' : 'Rascunho') ?></td><td class="cms-td-actions"><?= V::iconLink('/destaques/' . (int) $s['id'], 'Editar') ?><?= V::iconAction('slide-delete', 'Excluir', ['id' => $s['id']], 'Excluir este destaque?') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
